  const conCollezione = await apri("Collection", "[data-cname=collection]");
  const collezione = conCollezione ? righeDi(document.querySelector("[data-cname=collection]")) : [];
  const iFase = collezione.findIndex((riga) => /^phase\\s*\\d+/i.test(riga));
  const bambola =
    iFase > 0
      ? { nome: collezione[iFase - 1], fase: parseInt(collezione[iFase].match(/\\d+/)[0], 10), rarita: collezione[iFase + 1] || "?" }
      : undefined;

